import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router';
import './i18n/config.ts';
import { RootProvider as AltinnRootProvider, type LanguageCode } from '@altinn/altinn-components';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import i18n from 'i18next';
import { useTranslation } from 'react-i18next';
import App from './App.tsx';
import { Analytics } from './analytics/analytics.ts';
import { ANALYTICS_EVENTS } from './analytics/analyticsEvents.ts';
import { AuthProvider } from './components/Login/AuthContext.tsx';
import { QUERY_KEYS } from './constants/queryKeys.ts';
import { LoggerContextProvider } from './contexts/LoggerContext.tsx';
import { getPartyFromCookie } from './cookie.ts';
import { FeatureFlagProvider, loadFeatureFlags } from './featureFlags/FeatureFlagsProvider.tsx';
import { installDomMutationGuard } from './utils/domMutationGuard.ts';
import { normalizePathSlashes } from './utils/normalizePathSlashes.ts';

normalizePathSlashes();

console.info('App Version:', __APP_VERSION__);

let hasReportedDomRepair = false;
installDomMutationGuard({
  pageLanguage: () => i18n.language,
  onRepair: (trigger) => {
    if (hasReportedDomRepair) return;
    hasReportedDomRepair = true;
    Analytics.trackEvent(ANALYTICS_EVENTS.PAGE_DOM_MISMATCH_RECOVERED, { trigger });
  },
});

// Static mock build (vite build --mode pages, e.g. GitHub Pages): there is no BFF, so mocking is always on.
// The mock handlers and several components read `mock`/`playwrightId` from the URL, so make sure they are there.
const isStaticMock = import.meta.env.VITE_STATIC_MOCK === 'true';
if (isStaticMock) {
  const params = new URLSearchParams(window.location.search);
  if (params.get('mock') !== 'true' || !params.get('playwrightId')) {
    params.set('mock', 'true');
    if (!params.get('playwrightId')) {
      params.set('playwrightId', import.meta.env.VITE_STATIC_MOCK_PLAYWRIGHT_ID ?? '');
    }
    window.history.replaceState(
      window.history.state,
      '',
      `${window.location.pathname}?${params}${window.location.hash}`,
    );
  }
}

const urlParams = new URLSearchParams(window.location.search);
const isEnableMocking = urlParams.get('mock') === 'true';

async function enableMocking() {
  if (import.meta.env.DEV || isStaticMock) {
    if (isEnableMocking) {
      const { worker } = await import('./mocks/browser');
      return worker.start({ serviceWorker: { url: `${import.meta.env.BASE_URL}mockServiceWorker.js` } });
    }
  }
}

async function loadFeatures() {
  try {
    if (window.location.pathname === '/logout') {
      return {};
    }
    return await loadFeatureFlags();
  } catch {
    return {};
  }
}

const element = document.getElementById('root');

const RootProvider = ({ children }: { children: React.ReactNode }) => {
  const { i18n } = useTranslation();
  const languageCode = i18n.language as LanguageCode;

  return <AltinnRootProvider languageCode={languageCode}>{children}</AltinnRootProvider>;
};

if (element) {
  const root = ReactDOM.createRoot(element);
  const queryClient = new QueryClient();
  queryClient.setQueryData([QUERY_KEYS.ALTINN_COOKIE], getPartyFromCookie('AltinnPartyUuid') ?? '');

  Promise.all([enableMocking(), loadFeatures()]).then(([_, initialFlags]) => {
    root.render(
      <React.StrictMode>
        <LoggerContextProvider>
          <QueryClientProvider client={queryClient}>
            <BrowserRouter basename={import.meta.env.BASE_URL}>
              <FeatureFlagProvider initialFlags={isEnableMocking ? undefined : initialFlags}>
                <AuthProvider>
                  <RootProvider>
                    <App />
                  </RootProvider>
                </AuthProvider>
              </FeatureFlagProvider>
            </BrowserRouter>
          </QueryClientProvider>
        </LoggerContextProvider>
      </React.StrictMode>,
    );
  });
} else {
  console.error(`element with id "root" is not in DOM`);
}
